"use strict";

const fs = require("fs");
const path = require("path");

exports.summarize = function summarize(root) {
  const tempDir = path.join(root, ".tmp-scoped-fs");
  const file = path.join(tempDir, "meta.json");
  fs.mkdirSync(tempDir, { recursive: true });
  fs.writeFileSync(file, JSON.stringify({ name: "scoped", size: 12 }), "utf8");
  const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
  fs.rmSync(tempDir, { recursive: true, force: true });
  return `fsmeta:${parsed.name}:${parsed.size}`;
};
